import { collectKeys, durationToSeconds, firstOf, num, plateObjects, thumbnails } from "./common";
import type { GcodeChunks, GcodeParser, ParsedGcode } from "./types";

/**
 * PrusaSlicer 2.x plain (ASCII) .gcode. Facts from Joe's stand file (PrusaSlicer 2.7.2, Ender-3 V3 SE):
 * - first line: `; generated by PrusaSlicer 2.7.2 on <date> at <time> UTC`;
 * - no `;TIME:` line; totals and time estimates are text lines near the END
 *   (`; total filament used [g] = …`, `; estimated printing time (normal mode) = 1h 51m 43s`);
 * - all settings sit between `; prusaslicer_config = begin` and `; prusaslicer_config = end`;
 * - setting names differ from Orca: `temperature`, `bed_temperature`, `fill_density`, `perimeters`,
 *   `support_material`, and the printer is `printer_model` (e.g. ENDER3V3SE);
 * - objects are labelled only when "Label objects" is on (`; printing object … id:N copy N`);
 * - thumbnails, when enabled, are `; thumbnail begin WxH …` blocks.
 * SuperSlicer and old Slic3r write the same keys (SuperSlicer's block is `superslicer_config`).
 * Binary G-code (.bgcode) is a different format and is refused before any parser runs.
 */
export const prusaSlicerParser: GcodeParser = {
  id: "prusaslicer_gcode",
  version: "1",

  detect(head, tail) {
    return (
      /^; generated by (PrusaSlicer|SuperSlicer|Slic3r)/im.test(head) ||
      /^; (prusaslicer|superslicer)_config = begin/im.test(tail)
    );
  },

  parse({ head, tail, objectLines }: GcodeChunks): ParsedGcode {
    const raw: Record<string, string> = {};
    const block = tail.match(/^; (\w+)_config = begin([\s\S]*?)^; \1_config = end/m);
    if (block) {
      collectKeys(block[2]!, raw);
      // Totals and time estimates sit just before the config block.
      collectKeys(tail.slice(0, block.index).split(/\r?\n/).slice(-40).join("\n"), raw);
    } else {
      // Old Slic3r: no begin/end markers; settings are plain comment lines at the end.
      collectKeys(tail, raw);
    }

    const generated = head.match(/; generated by (PrusaSlicer|SuperSlicer|Slic3r)\S*\s+([\d.]+(?:-\w+)?)/i);
    const supportsEnabled =
      raw["support_material"] == null ? null : raw["support_material"] === "1" || raw["support_material"] === "true";
    const fill = raw["fill_density"];

    return {
      parser: this.id,
      parserVersion: this.version,
      slicerName: generated?.[1] ?? "PrusaSlicer",
      slicerVersion: generated?.[2] ?? null,
      printerModel: raw["printer_model"] || raw["printer_settings_id"] || null,
      nozzleMm: num(firstOf(raw["nozzle_diameter"])),
      material: firstOf(raw["filament_type"]) || null,
      colour: firstOf(raw["filament_colour"]) || null,
      layerHeightMm: num(raw["layer_height"]),
      // PrusaSlicer doesn't write a layer count; counting would mean scanning every move.
      totalLayers: null,
      totalGrams: num(raw["total filament used [g]"]) ?? num(firstOf(raw["filament used [g]"])),
      totalMm: num(firstOf(raw["filament used [mm]"])),
      totalCm3: num(firstOf(raw["filament used [cm3]"])),
      estimatedSeconds: durationToSeconds(raw["estimated printing time (normal mode)"]),
      nozzleTempC: num(firstOf(raw["temperature"])),
      bedTempC: num(firstOf(raw["bed_temperature"])),
      bedType: null,
      // fill_density is "15%" in new versions and "0.15" in very old ones.
      infillPct: fill == null ? null : fill.includes("%") ? num(fill) : (num(fill) ?? 0) * 100,
      infillPattern: raw["fill_pattern"] || null,
      wallLoops: num(raw["perimeters"]),
      supportType: supportsEnabled === false ? "none" : (raw["support_material_style"] ?? null),
      supportsEnabled,
      slicerFilamentCost: num(firstOf(raw["filament_cost"])),
      objects: plateObjects(objectLines),
      thumbnails: thumbnails(head),
      rawHeader: raw,
      estimated: {},
    };
  },
};
